function buildPrompt(url) {
return [
`Read this webpage: ${url}`,
"",
"Create a useful summary and extract the important information.",
"Include key facts, names, dates, and any IOCs if present.",
"Call out anything that appears unverified, then suggest 3 to 5 next checks."
].join("\n");
}

const link = document.getElementById("rps-openai-link");
if (!link) return;

const url = getCanonicalUrl();
const prompt = buildPrompt(url);

link.href = "https://chatgpt.com/?q=" + encodeURIComponent(prompt) + "&hints=search";
})();

